import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import {createHash} from 'node:crypto';
import {validateWoundStagingProjection} from '../check-wound-staging-projection.mjs';

// Captured from the actual synthetic Staging rollback fixture, not generated by this test.
const fixtureUrl=new URL('./fixtures/wound-staging-synthetic-20261022.json',import.meta.url);
const fixtureText=fs.readFileSync(fixtureUrl,'utf8');
const fixture=JSON.parse(fixtureText);
const clone=()=>structuredClone(fixture);
const otherId='12345678-1234-4234-8234-123456789012';

test('actual SQL path, independent review and retained receipts satisfy current Web contracts',()=>{
 assert.equal(validateWoundStagingProjection(clone()),true);
});

test('actual historical request receipt stays at its own head after a later independent decision',()=>{
 const request=fixture.reviewReceipt.original,decision=fixture.decisionReceipt.original;
 assert.equal(request.history.length,1);
 assert.equal(request.rootId,request.history[0].id);
 assert.equal(request.headId,request.rootId);
 assert.equal(decision.rootId,request.rootId);
 assert.equal(decision.history.length,2);
 assert.notEqual(decision.headId,request.headId);
 assert.notEqual(fixture.reviewPacket.actorId,fixture.decisionPacket.actorId);
 assert.deepEqual(decision.history[0],request.history[0]);
 assert.equal(validateWoundStagingProjection(clone()),true);
});

test('actual microsecond history and native escalation fingerprint survive JSON transport',()=>{
 const history=fixture.pathReceipt.original.history;
 assert.match(history[0].recordedAt,/\.345678\+00:00$/);
 assert.match(history[1].recordedAt,/\.456789\+00:00$/);
 const packet=fixture.reviewPacket;
 const source=packet.sources.escalations.find(x=>x.id===packet.woundOriginal.headId);
 assert.ok(source);
 assert.equal(source.fingerprint,packet.woundOriginal.contentFingerprint);
 assert.equal(source.payload.resolution_state,'resolved');
});

test('retained SQL fixture contains only scoped packet/receipt evidence and no Auth material',()=>{
 assert.deepEqual(Object.keys(fixture).sort(),['clientId','decisionPacket','decisionReceipt','pathPacket','pathReceipt','reviewPacket','reviewReceipt','tenantId','woundId']);
 assert.doesNotMatch(fixtureText,/session|token|auth_user|email|password|bearer|claims/i);
});

test('retained SQL fixture bytes match the recorded provenance hash',()=>{
 const provenance=JSON.parse(fs.readFileSync(new URL('./fixtures/wound-staging-synthetic-20261022.provenance.json',import.meta.url),'utf8'));
 assert.equal(createHash('sha256').update(fixtureText).digest('hex'),provenance.sha256);
 assert.equal(provenance.synthetic,true);
 assert.equal(provenance.authHttpVerified,false);
});

const mutations=[
 ['foreign tenant scope',p=>{p.tenantId=otherId;}],
 ['foreign client scope',p=>{p.clientId=otherId;}],
 ['foreign wound scope',p=>{p.woundId=otherId;}],
 ['lost path receipt request identity',p=>{p.pathReceipt.requestId=otherId;}],
 ['lost decision receipt request identity',p=>{p.decisionReceipt.requestId=otherId;}],
 ['altered saved path content',p=>{p.pathReceipt.original.history.at(-1).payload.observation.narrative+=' changed';}],
 ['wrong saved path author',p=>{p.pathReceipt.original.history.at(-1).recordedBy=otherId;p.pathReceipt.original.recordedBy=otherId;}],
 ['changed path reason despite matching request echo',p=>{p.pathPacket.reason+=' changed';p.pathReceipt.packet.reason=p.pathPacket.reason;}],
 ['missing historical path revision',p=>{p.pathReceipt.original.history.shift();}],
 ['path root detached from first retained event',p=>{p.pathReceipt.original.rootId=otherId;}],
 ['foreign tenant hidden in older path payload',p=>{p.pathReceipt.original.history[0].payload.tenantId=otherId;}],
 ['foreign client hidden in older path payload',p=>{p.pathReceipt.original.history[0].payload.clientId=otherId;}],
 ['foreign wound hidden in older path payload',p=>{p.pathReceipt.original.history[0].payload.woundId=otherId;}],
 ['historical observation time differs by one microsecond',p=>{p.pathReceipt.original.history[0].payload.observedAt='2026-10-21T06:04:00.345679Z';}],
 ['same event identity reused across historical revisions',p=>{const o=p.pathReceipt.original;o.history[0].id=o.headId;o.rootId=o.headId;o.history[1].previousId=o.headId;}],
 ['derived source hash instead of retained native escalation hash',p=>{p.reviewPacket.sources.escalations.find(x=>x.id===p.reviewPacket.woundOriginal.headId).fingerprint='sha256:'+'0'.repeat(64);}],
 ['initial review root differs from its first actual event',p=>{p.reviewReceipt.original.rootId=otherId;}],
 ['independent decision targets another wound fingerprint',p=>{p.decisionReceipt.original.woundFingerprint='sha256:'+'0'.repeat(64);}],
 ['decision own original replaced by its receipt envelope',p=>{p.decisionReceipt.original=structuredClone(p.decisionReceipt);}],
 ['valid decision packet echo belongs to another request',p=>{p.decisionReceipt.packet.requestId=otherId;}],
];
for(const [name,mutate] of mutations)test(`actual SQL evidence rejects ${name}`,()=>{
 const changed=clone();mutate(changed);
 assert.throws(()=>validateWoundStagingProjection(changed),{code:'ERR_ASSERTION'});
});
